  await page.waitForSelector('.cpu-tooltip');
  assert.match(await page.locator('.cpu-tooltip').innerText(), /CPU/);
  assert.match(await page.locator('.cpu-tooltip').innerText(), /%/);
  await page.mouse.move(box.x + box.width * .3, box.y + box.height / 2);
  await page.mouse.down();
  await page.mouse.move(box.x + box.width * .6, box.y + box.height / 2, {steps: 10});
  await page.mouse.up();
  await page.waitForFunction(() => document.querySelector('.chart-hint').textContent.includes('Для возврата'));
  await page.waitForTimeout(2200);
