import React from 'react';
import {createRoot} from 'react-dom/client';
import {ThemeProvider} from '@gravity-ui/uikit';
import Yagr from '@gravity-ui/yagr';
import {CpuChart} from './src/CpuChart';
import {createDemoHistory, appendCpuSample} from './src/cpuData';
const host = document.createElement('div');
host.style.width = '800px';
document.body.appendChild(host);
const root = createRoot(host);
let data = createDemoHistory();
let theme = 'light';
let instance;
const original = Yagr.prototype.reflow;
Yagr.prototype.reflow = function(...args) {
  if (host.contains(this.root)) instance = this;
  return original.apply(this, args);
};
window.chartCheck = {
  render() { root.render(<React.StrictMode><ThemeProvider theme={theme}><CpuChart data={data} /></ThemeProvider></React.StrictMode>); },
  update() { data = appendCpuSample(data, data.timeline.at(-1) + 2000, 91); this.render(); },
  clear() { data = {timeline: [], values: []}; this.render(); },
  dark() { theme = 'dark'; this.render(); },
  range() { return instance.getScales('x').x; },
  instance() { return {points: instance.uplot.data[0].length, last: instance.uplot.data[1].at(-1), y: instance.getScales('y').y}; },
  unmount() { root.unmount(); host.remove(); Yagr.prototype.reflow = original; },
  host,
};
window.chartCheck.render();
EOF
