  const errors = [];
  page.on('pageerror', error => errors.push(error.message));
  await page.addInitScript(() => {
    const observers = new Set(), frames = new Set(), listeners = new Set();
    const NativeObserver = ResizeObserver;
    window.ResizeObserver = class extends NativeObserver {
      observe(target, ...args) {observers.add(this); super.observe(target, ...args);}
      disconnect() {observers.delete(this); super.disconnect();}
    };
    const request = requestAnimationFrame, cancel = cancelAnimationFrame;
    window.requestAnimationFrame = callback => {
      const id = request(time => {frames.delete(id); callback(time);});
      frames.add(id); return id;
    };
    window.cancelAnimationFrame = id => {frames.delete(id); cancel(id);};
    const add = document.addEventListener.bind(document), remove = document.removeEventListener.bind(document);
    document.addEventListener = (type, handler, options) => {if (type === 'mouseup') listeners.add(handler); add(type, handler, options);};
    document.removeEventListener = (type, handler, options) => {if (type === 'mouseup') listeners.delete(handler); remove(type, handler, options);};
